Here is the problem description:
<problem_description>
All bus tickets in Berland have their numbers. A number consists of $$$n$$$ digits ($$$n$$$ is even). Only $$$k$$$ decimal digits $$$d_1, d_2, \dots, d_k$$$ can be used to form ticket numbers. If $$$0$$$ is among these digits, then numbers may have leading zeroes. For example, if $$$n = 4$$$ and only digits $$$0$$$ and $$$4$$$ can be used, then $$$0000$$$, $$$4004$$$, $$$4440$$$ are valid ticket numbers, and $$$0002$$$, $$$00$$$, $$$44443$$$ are not.A ticket is lucky if the sum of first $$$n / 2$$$ digits is equal to the sum of remaining $$$n / 2$$$ digits. Calculate the number of different lucky tickets in Berland. Since the answer may be big, print it modulo $$$998244353$$$.
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
import java.util.Scanner;

public class LuckyTickets {

    private static final int MOD = 998244353;
    private static final int TWO_POWER = 23;
    private static final int PRIMITIVE_ROOT = 15311432;

    private static int reverseBits(int x, int bits) {
        return Integer.reverse(x) >>> (32 - bits);
    }

    private static long power(long b, long e) {
        long res = 1;
        b %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1;
        }
        return res;
    }

    private static long modInverse(long x) {
        return power(x, MOD - 2);
    }

    private static long[] generateRoots(int k, boolean isInverse) {
        long root = power(PRIMITIVE_ROOT, power(2, TWO_POWER - k));
        if (isInverse) root = modInverse(root);
        long[] r = new long[k];
        r[k - 1] = root;
        for (int i = k - 1; i > 0; i--) {
            r[i - 1] = (r[i] * r[i]) % MOD;
        }
        return r;
    }

    private static long[] permute(long[] input, int k) {
        long[] output = new long[input.length];
        for (int i = 0; i < input.length; i++) {
            output[reverseBits(i, k)] = input[i];
        }
        return output;
    }

    private static long[] transform(long[] poly, int k, boolean inverse) {
        poly = permute(poly, k);
        long[] roots = generateRoots(k, inverse);
        for (int s = 0; s < k; s++) {
            int segmentLength = 1 << s;
            for (int start = 0; start < poly.length; start += 2 * segmentLength) {
                long omega = 1;
                for (int j = start; j < start + segmentLength; j++) {
                    long temp = (omega * poly[j + segmentLength]) % MOD;
                    long u = poly[j];
                    poly[j] = (u + temp) % MOD;
                    poly[j + segmentLength] = (u - temp) % MOD;
                    omega = (roots[s] * omega) % MOD;
                }
            }
        }
        return poly;
    }

    public static void main(String[] args) {
        Scanner reader = new Scanner(System.in);
        int n = reader.nextInt() / 2;
        int count = reader.nextInt();
        int[] inputs = new int[count];
        int largest = 0;
        for (int i = 0; i < count; i++) {
            inputs[i] = reader.nextInt();
            largest = Math.max(largest, inputs[i]);
        }
        int requiredLength = n * largest + 1;
        int degree = 0;
        int length = 1;
        while (length < requiredLength) {
            length <<= 1;
            degree++;
        }
        long[] polynomial = new long[length];
        for (int val : inputs) {
            polynomial[val] = 1;
        }
        polynomial = transform(polynomial, degree, false);
        for (int i = 0; i < length; i++) {
            polynomial[i] = power(polynomial[i], n);
        }
        polynomial = transform(polynomial, degree, true);
        long total = 0;
        for (int i = 0; i < length; i++) {
            total = (total + polynomial[i] * polynomial[i]) % MOD;
        }
        long scale = modInverse(length);
        System.out.println(((total * scale % MOD) * scale) % MOD);
    }
}
